type JobHandle struct {
    id     int
    handle cgo.Handle
    result chan string
    done   chan struct{}
}

var (
    jobs   = make(map[int]chan string)
    jobsMu sync.Mutex
)

//export jobCallback
func jobCallback(id C.int, result *C.char, len C.size_t, user unsafe.Pointer) {
    handle := cgo.Handle(user)
    if ch, ok := handle.Value().(chan string); ok {
        jobsMu.Lock()
        defer jobsMu.Unlock()
        jobs[id] = ch
        ch <- C.GoStringN(result, C.int(len))
    }
